def solve_islands(grid):
    """Find connected components of background that don't touch border, fill with 4"""
    h, w = len(grid), len(grid[0])

    # Find background color (most frequent)
    colors = {}
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            colors[cell] = colors.get(cell, 0) + 1
    bg_color = max(colors.keys(), key=lambda c: colors[c])

    result = [row[:] for row in grid]  # Copy

    visited = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg_color and (r,c) not in visited:
                # BFS to find connected component
                comp = []
                queue = [(r,c)]

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    comp.append((curr_r, curr_c))

                    # Check 8 neighbors
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if grid[nr][nc] == bg_color and (nr, nc) not in visited:
                                    queue.append((nr, nc))

                # Check if component touches border
                touches_border = any(p[0] in [0, h-1] or p[1] in [0, w-1] for p in comp)

                # If doesn't touch border, fill with 4
                if not touches_border:
                    for (rr, cc) in comp:
                        result[rr][cc] = 4

    return result

